import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import {
	dropdownCaretDown,
	dropdownCaretRight,
	x as xIcon,
} from "../../../icons/index";
import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

/**
 * @since 2.0
 * @status stable
 *
 * @data-testid base - The main nav item trigger element.
 * @data-testid drawer-close - The close button rendered for the nav item's drawer content.
 *
 * @slot prefix - The nav item's prefix.
 * @slot content - The nav item's content.
 * @slot drawer-header - The drawers header area.
 * @slot menu - Content of the drawer.
 *
 *
 * @part base - The component's base wrapper.
 * @part pointer - The nav items's selected item pointer.
 * @part prefix - The nav items's prefix.
 * @part content - The nav items's content.
 * @part suffix - The nav items's suffix.
 * @part drawer - The drawers's base wrapper.
 * @part drawer-container - The drawers's container wrapper.
 * @part drawer-header - The drawers's header wrapper.
 * @part drawer-close - The drawers's close button.
 * @part drawer-content - The component's content area.
 */

@Component({
	tag: "hbr-nav-item",
	styleUrl: "nav-item.scss",
	shadow: true,
})
export class NavItem {
	componentId = `nav-${generateShortID()}`;
	baseRef: HTMLElement;
	tooltipRef: HTMLHbrTooltipElement;
	contentObserver: MutationObserver;
	hasPopover = false;
	activeTimer = null;
	hoverTimer = null;

	//** for all accessibility attribute. */
	@State() ariaObject = { label: "" };

	@State() hasMenu = false;
	@State() hasContent = false;

	@Element() host: HTMLHbrNavItemElement;

	/** Set to true to draw the nav item in an active state. */
	@Prop({ reflect: true }) active = false;

	/** Set to true to draw the nav item in an selected state. */
	@Prop({ reflect: true }) selected = false;

	/** Used to set nav item as switcher. */
	@Prop({ reflect: true }) switcher = false;

	/** Used to show switcher arrow down icon. */
	@Prop() switcherArrowDown = false;

	/** When another nav item was active before we don't need to show drawer animation. */
	@Prop({ reflect: true }) noTransform = false;

	/** collapsed state in side nav. */
	@Prop({ reflect: true }) collapsed = false;

	/** 'aria-label' attribute when a label is not set. */
	@Prop() arialabel = "";

	/** The item's color sentiment. */
	@Prop({ reflect: true }) sentiment:
		| "neutral"
		| "success"
		| "warning"
		| "danger"
		| "info"
		| "error";

	/** If do not show collapsible label when in side nav. */
	@Prop({ reflect: true }) titleless = false;

	/** Used to show text in tooltip if necessary. */
	@Prop({ reflect: true }) tooltipText = "";

	/** Flag to put "new" tag next to label. */
	@Prop() newTag = false;

	/** Nav item value (can be used as path). */
	@Prop({ reflect: true }) value = "";

	@Prop() hoverDelay = 0;

	/** Nav drawer animation duration */
	@Prop() drawerTransitionDuration = 300;

	/** Emitted to handle uncontrolled component use cases. */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	/** Emitted when a nav item is hoverer. */
	@Event({ eventName: "hbr-hover" }) hbrHover: EventEmitter;

	/** Emitted when mouse leaves nav item. */
	@Event({ eventName: "hbr-leave" }) hbrLeave: EventEmitter;

	/** Emitted when the nav item is activated. */
	@Event({ eventName: "hbr-active" }) hbrActive: EventEmitter;

	/** Emitted when the nav item is activated. */
	@Event({ eventName: "hbr-hide" }) hbrDrawerClose: EventEmitter<boolean>;

	/** Emitted when a key down. */
	@Event({ eventName: "hbr-keydown" }) hbrKeydown: EventEmitter;

	/** Emitted when the nav item is activated. */
	@Event({ eventName: "hbr-nav-item-select" })
	hbrItemSelect: EventEmitter<HTMLHbrNavItemElement>;

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	componentDidLoad() {
		document.addEventListener("keydown", this.handleKeyDown);
		const slot = this.host.shadowRoot.querySelector(
			'slot[name="menu"]',
		) as HTMLSlotElement;
		if (slot?.assignedNodes()?.length) {
			this.hasPopover = true;
		}
		this.onSlotUpdate("content");
		this.onSlotUpdate("content-header");
	}

	disconnectedCallback() {
		document.removeEventListener("keydown", this.handleKeyDown);
		this.contentObserver?.disconnect();
	}

	private handleKeyDown = (event: KeyboardEvent) => {
		if (this.active && event.key === "Escape") {
			this.drawerClose(true);
		}
	};

	/** Sets focus to the tab. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.baseRef.focus(options);
		this.setTooltipVisibility(true);
	}

	/** Removes focus from the tab. */
	@Method()
	async removeFocus() {
		this.baseRef.blur();
		this.setTooltipVisibility(false);
	}

	@Method()
	async drawerClose(withKeyboard = false) {
		this.hbrDrawerClose.emit(withKeyboard);
	}

	@Method()
	async setSelectedItem(navItem) {
		this.hbrItemSelect.emit(navItem);
	}

	@Method()
	async onSidePanelItemSelect(keyboard = false) {
		this.hbrClick.emit({ popover: this.hasMenu, keyboard: keyboard });
	}

	@Method()
	async haveMenu() {
		return this.hasMenu;
	}

	@Method()
	async setTooltipVisibility(visible = true) {
		this.tooltipRef.open = visible;
	}

	onSidePanelItemKeyDown = async (event: KeyboardEvent) => {
		this.hbrKeydown.emit(event);
		if ([" ", "Enter", "ArrowRight"].includes(event.key)) {
			event.preventDefault();
			this.onSidePanelItemSelect(true);
		}
	};

	handleCloseDrawerKeyDown = (event) => {
		if ([" ", "Enter", "Escape", "ArrowLeft"].includes(event.key)) {
			this.drawerClose(true);
		} else if (event.key === "ArrowDown") {
			const target = event?.target?.parentElement.nextElementSibling;
			const menuSlot = target.querySelector("slot[name='menu']");
			if (menuSlot) {
				const content = menuSlot.assignedElements();
				if (content.length) {
					const menuItems = content[0].querySelector("hbr-menu-item");
					menuItems.setFocus();
				}
			}
		}
		event.stopPropagation();
	};

	@Watch("active")
	/**
	 * Handles the active state change of a tab navigation item and manages drawer animations.
	 *
	 * This method manages a sliding in/out animation sequence for the drawer element:
	 * - Emits an active event when the tab becomes active
	 * - Toggles drawer CSS classes to create smooth transitions
	 * - Handles animation delays to prevent overlapping animations when switching between tabs
	 * - Uses a timer-based approach to coordinate class additions/removals for proper animation sequencing
	 *
	 * Animation Flow:
	 * - When deactivating: removes the delay class, then removes the active class after delay
	 * - When activating: adds active class, and optionally adds delay class based on previous state
	 * - The delay class ensures smooth transitions when switching from one active tab to another
	 *
	 * @param {boolean} active - Whether the tab is becoming active (true) or inactive (false)
	 *
	 * @remarks
	 * - Queries the closest shell-nav component to find the previously active nav item
	 * - Respects the `noTransform` flag to determine animation delay behavior
	 * - Clears any pending animation timers before starting a new sequence
	 * - Animation timing is controlled by the drawer_delay constant
	 */
	handleTabActive(active) {
		active && this.hbrActive.emit({ tab: this.host });

		const shellMav = this.host.closest(
			"hbr-shell-nav",
		) as HTMLHbrShellNavElement;
		const prevActiveNav = shellMav?.querySelector("hbr-nav-item[active]");

		const drawer = this.host.shadowRoot.querySelector(
			".nav-item__drawer",
		) as HTMLElement;

		if (drawer) {
			if (!active) {
				drawer.classList.remove("nav-item__drawer-delay-active");
			} else {
				drawer.classList.add("nav-item__drawer-active");
			}

			if (prevActiveNav && prevActiveNav !== this.host && this.noTransform) {
				drawer.classList.add("nav-item__drawer-delay-active");
			}

			clearTimeout(this.activeTimer);
			this.activeTimer = setTimeout(() => {
				if (!active) {
					drawer.classList.remove("nav-item__drawer-active");
				} else {
					if (
						!(prevActiveNav && prevActiveNav !== this.host && this.noTransform)
					) {
						drawer.classList.add("nav-item__drawer-delay-active");
					}
				}
			}, this.drawerTransitionDuration);
		}
	}

	onSidePanelItemMouseEnter = () => {
		this.hbrHover.emit({ popover: this.hasMenu });
	};

	onSidePanelItemMouseLeave = () => {
		this.hbrLeave.emit();
	};

	handleSlotChange() {
		this.hasMenu = hasSlot(this.host, "menu");
	}

	getSlotHasContent = (slot: HTMLSlotElement) => {
		return (
			slot?.assignedNodes({ flatten: true })?.some((node) => {
				if ((node.textContent ?? "").trim().length > 0) {
					return true;
				}

				return node instanceof HTMLElement && node.children.length > 0;
			}) ?? false
		);
	};

	refreshContentState = () => {
		const slot = this.host.shadowRoot.querySelector(
			'slot[name="content"]',
		) as HTMLSlotElement;
		this.hasContent = this.getSlotHasContent(slot);
	};

	observeContentSlot = () => {
		const slot = this.host.shadowRoot.querySelector(
			'slot[name="content"]',
		) as HTMLSlotElement;

		this.contentObserver?.disconnect();

		if (!slot) {
			this.hasContent = false;
			return;
		}

		this.refreshContentState();

		if (!this.contentObserver) {
			this.contentObserver = new MutationObserver(() => {
				this.refreshContentState();
			});
		}

		slot.assignedNodes({ flatten: true }).forEach((node) => {
			this.contentObserver.observe(node, {
				childList: true,
				characterData: true,
				subtree: true,
			});
		});
	};

	onSlotUpdate = (slotName) => {
		const slot = this.host.shadowRoot.querySelector(
			`slot[name="${slotName}"]`,
		) as HTMLSlotElement;

		if (slotName === "content") {
			this.observeContentSlot();
		}

		// only first slot
		if (slot?.assignedElements()?.length) {
			const label = slot.assignedElements()[0].textContent?.trim();

			if (!label) {
				return;
			}

			this.ariaObject = JSON.parse(
				JSON.stringify({
					label,
				}),
			);
		}
	};

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const isTooltipEnabled = !(
			this.tooltipText?.length &&
			this.collapsed &&
			this.titleless &&
			!this.active
		);

		return (
			<Host
				id={this.host.id || this.componentId}
				sentiment={this.sentiment}
				aria-label={
					this.arialabel === "" ? this.ariaObject.label : this.arialabel
				}
				aria-haspopup={this.hasPopover ? "true" : "false"}
				aria-current={this.hasMenu ? null : this.selected ? "true" : "false"}
				aria-expanded={this.hasMenu ? (this.active ? "true" : "false") : null}
				role="menuitem"
			>
				<div
					class={{
						"nav-item__wrapper": true,
						"nav-item__wrapper-active": this.active,
						"nav-item__wrapper--collapsed": this.collapsed,
						"nav-item__wrapper--titleless": this.collapsed && this.titleless,
					}}
				>
					<div
						part="base"
						data-testid="base"
						// biome-ignore lint/a11y: nav item trigger is the keyboard focus target
						tabIndex={0}
						ref={(el) => {
							this.baseRef = el;
						}}
						onMouseEnter={() => {
							clearTimeout(this.hoverTimer);
							this.hoverTimer = setTimeout(() => {
								this.onSidePanelItemMouseEnter();
							}, this.hoverDelay);
						}}
						onClick={() => {
							this.onSidePanelItemSelect(false);
						}}
						onMouseLeave={this.onSidePanelItemMouseLeave}
						onKeyDown={this.onSidePanelItemKeyDown}
						class={{
							"nav-item": true,
							// variants

							"nav-item--switcher": this.switcher,
							"nav-item--popover": this.hasPopover,
							"nav-item--no-label": this.titleless,

							// states
							"nav-item--active": this.active,
							"nav-item--selected": this.selected,
							"nav-item--collapsed": this.collapsed,
						}}
					>
						<div part="pointer" class="nav-item__selected-pointer" />
						<span part="prefix" class="nav-item__prefix">
							<slot name="prefix" />
						</span>
						<div part="content" class="nav-item__content">
							{!this.collapsed && (
								<slot
									name="content-header"
									onSlotchange={() => this.onSlotUpdate("content-header")}
								/>
							)}
							<slot
								name="content"
								onSlotchange={() => this.onSlotUpdate("content")}
							/>
							{!this.hasContent ? (
								<span class="nav-item__content-placeholder">{"\u2014"}</span>
							) : null}
						</div>
						{!this.collapsed && this.newTag && (
							<span part="tag" class="nav-item__label-tag">
								<slot name="tag" />
							</span>
						)}
						<span part="suffix" class="nav-item__suffix">
							{this.switcher && this.switcherArrowDown ? (
								<hbr-icon slot="suffix" asset={dropdownCaretDown} />
							) : null}
							{this.hasMenu ? (
								<hbr-icon
									slot="suffix"
									asset={
										customSystemIcons?.["dropdown-caret-right"] ||
										dropdownCaretRight
									}
								/>
							) : null}
						</span>
					</div>
				</div>
				{this.hasMenu ? (
					<div
						part="drawer"
						class={{
							"nav-item__drawer": true,
							"nav-item__drawer-collapsed-item": this.collapsed,
							"nav-item__drawer-collapsed-item-titleless":
								this.collapsed && this.titleless,
						}}
						style={{
							"--drawer-transition-duration": `${this.drawerTransitionDuration}ms`,
						}}
						aria-hidden={!this.active}
						aria-label={
							this.arialabel === "" ? this.ariaObject.label : this.arialabel
						}
					>
						<div
							part="drawer-container"
							class={{
								"nav-item__drawer-wrapper": true,
								"nav-item__drawer-wrapper-active": this.active,
								"nav-item__drawer-wrapper-no-transform": this.noTransform,
							}}
						>
							<div class="nav-item__drawer-header" part="drawer-header">
								<slot name="drawerHeader" />
								<div
									class="nav-item__drawer-close"
									role="button"
									aria-label={`Close ${
										this.arialabel === ""
											? this.ariaObject.label
											: this.arialabel
									}`}
									onClick={() => {
										this.drawerClose();
									}}
									part="drawer-close"
									data-testid="drawer-close"
									tabIndex={0}
									onKeyDown={this.handleCloseDrawerKeyDown}
								>
									<hbr-icon
										style={{
											display: "flex",
											alignItems: "center",
											fontSize: "var(--hbr-font-size-md)",
											cursor: "pointer",
											width: "16px",
											height: "16px",
										}}
										asset={customSystemIcons?.["x-icon"] || xIcon}
									/>
								</div>
							</div>
							<div class="nav-item__drawer-menu" part="drawer-content">
								<slot name="menu" onSlotchange={this.handleSlotChange} />
							</div>
						</div>
					</div>
				) : null}
				<hbr-portal>
					<hbr-tooltip
						ref={(el) => {
							this.tooltipRef = el;
						}}
						content={this.tooltipText}
						disabled={isTooltipEnabled}
						skidding={this.switcher ? 12 : 3}
						distance={12}
						placement="left-start"
						anchor={this.baseRef}
					/>
				</hbr-portal>
			</Host>
		);
	}
}
